export namespace audit {
    export interface IngestAuditRequest {
        authorization: string
        action: string
        targetType: string
        targetId: string
        metadata?: { [key: string]: any }
        /**
         * Spec 205 FR-005: when an agent NHI generates the record (via OPC
         * axiomregent), it passes both principals: the NHI subject and the
         * human it acts for. Populated onto the row when present, NULL otherwise.
         */
        nhiSub?: string

        onBehalfOf?: string
    }

    export interface IngestAuditResponse {
        ok: true
    }

    export interface ListProjectAuditRecordsResponse {
        rows: ProjectAuditRow[]
    }

    export interface ProjectAuditRow {
        id: string
        actorUserId: string
        action: string
        targetType: string
        targetId: string
        createdAt: string
        metadata: { [key: string]: any }
    }

    export class ServiceClient {
        private baseClient: BaseClient

        constructor(baseClient: BaseClient) {
            this.baseClient = baseClient
            this.ingestAuditRecord = this.ingestAuditRecord.bind(this)
            this.listProjectAuditRecords = this.listProjectAuditRecords.bind(this)
        }

        /**
         * Seam B: Ingest audit records from OPC axiomregent.
         * POST /api/audit-records — M2M bearer token auth (OIDC JWT or static fallback).
         */
        public async ingestAuditRecord(params: IngestAuditRequest): Promise<IngestAuditResponse> {
            // Convert our params into the objects we need for the request
            const headers = makeRecord<string, string>({
                authorization: params.authorization,
            })

            // Construct the body with only the fields which we want encoded within the body (excluding query string or header fields)
            const body: Record<string, any> = {
                action:     params.action,
                metadata:   params.metadata,
                nhiSub:     params.nhiSub,
                onBehalfOf: params.onBehalfOf,
                targetId:   params.targetId,
                targetType: params.targetType,
            }

            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("POST", `/api/audit-records`, JSON.stringify(body), {headers})
            return await resp.json() as IngestAuditResponse
        }

        /**
         * Spec 175 FR-007 — list recent audit_log rows scoped to a project.
         *
         * The default `limit` is 5 to match the dashboard panel; callers asking
         * for more raise to a hard cap of 50.
         */
        public async listProjectAuditRecords(projectId: string, params: {
    limit?: number
}): Promise<ListProjectAuditRecordsResponse> {
            // Convert our params into the objects we need for the request
            const query = makeRecord<string, string | string[]>({
                limit: params.limit === undefined ? undefined : String(params.limit),
            })

            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/api/projects/${encodeURIComponent(projectId)}/audit`, undefined, {query})
            return await resp.json() as ListProjectAuditRecordsResponse
        }
    }
}

