        public async postExtractionOutput(projectId: string, objectId: string, params: PostExtractionOutputRequest): Promise<PostExtractionOutputResponse> {
            // Convert our params into the objects we need for the request
            const headers = makeRecord<string, string>({
                "x-knowledge-schema-version": params.schemaVersion,
            })

            // Construct the body with only the fields which we want encoded within the body (excluding query string or header fields)
            const body: Record<string, any> = {
                orgId:  params.orgId,
                output: params.output,
            }

            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("POST", `/api/projects/${encodeURIComponent(projectId)}/knowledge/objects/${encodeURIComponent(objectId)}/extraction-output`, JSON.stringify(body), {headers})
            return await resp.json() as PostExtractionOutputResponse
        }

